import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] p = new int[n];
        int sum = 0;

        for (int i = 0; i < n; i++) {
            p[i] = sc.nextInt();
            sum += p[i];
        }

        int target = sum / n;

        for (int i = 0; i < n; i++) {
            System.out.println(target - p[i]);
        }

        sc.close();
    }
}
